---level12 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl12_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		if dialog.showFixedTime("Level12-1", faceJingya,3) ==1 then break end			if dialog.show("Level12-2", faceWunai) ==1 then break end		if dialog.show("Level12-3", faceRenzhen) ==1 then break end				--set story viewed flag        global.setBool("lvl12_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()endonRoleReachedMoon = function()	game.pauseLogic()    if global.isLevelPassed(14) then		if global.getBool("stg_b1") then dialog.setSkipEnabled(true) end		repeat			sound.play("60-2")			if dialog.show("Stage1F-1", faceWunai) ==1 then break end			sound.play("54-1")			if dialog.show("Stage1F-2", faceManyi) ==1 then break end			sound.play("58-1")			if dialog.show("Stage1F-3", faceShengqi) ==1 then break end			if dialog.show("Stage1F-4", faceZhoumei) ==1 then break end			if dialog.show("Stage1F-5", faceBujie) ==1 then break end			if dialog.show("Stage1F-6", faceRenzhen) ==1 then break end			global.setBool("stg_b1")		until true		dialog.setSkipEnabled(false)    end    game.success()end